COPY public."StarPromoRedemption" (id, "promoId", "userId", "redeemedAt", "usedAt") FROM stdin;
\.
COPY public."StayBooking" (id, "reservationId", "propertyId", "guestUserId", "checkIn", "checkOut", guests, "pricePerNight", "totalAmount", "depositAmount", "depositStatus", "escrowTxHash", status, "createdAt", "updatedAt") FROM stdin;
\.
COPY public."SystemAuditLog" (id, "actorId", action, "targetId", "ipAddress", "userAgent", metadata, "createdAt") FROM stdin;
